def build_grid_graph(N):
    """Builds the full adjacency list for an N x N grid."""
    graph = {}
    nodes = {}
    for r in range(N):
        for c in range(N):
            node = (r, c)
            nodes[node] = True
            graph[node] = []
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighbor = (nr, nc)
                    graph[node].append(neighbor)
    return graph

def apply_constraints(graph, marked_cells):
    """Removes edges where both endpoints are in marked_cells."""
    constrained_graph = {node: list(neighbors) for node, neighbors in graph.items()}
    marked_set = set(marked_cells)

    edges_to_remove = set()
    # Iterate through all cells and their neighbors
    for r in range(4):
        for c in range(4):
            u = (r, c)
            if u in marked_set:
                for neighbor in constrained_graph[u]:
                    v = neighbor
                    if v in marked_set:
                        # This edge must be removed
                        # We remove both directions for adjacency list consistency
                        edges_to_remove.add((u, v))
                        edges_to_remove.add((v, u))

    # Apply removal
    for u, v in edges_to_remove:
        if v in constrained_graph[u]:
            constrained_graph[u].remove(v)
        if u in constrained_graph[v]:
            constrained_graph[v].remove(u)

    return constrained_graph

# Test case: 4x4 board, 2x2 marked corner
N = 4
M_4x4 = [(0, 0), (0, 1), (1, 0), (1, 1)] 

# Build the full graph
full_graph = build_grid_graph(N)

# Apply constraints
constrained_graph = apply_constraints(full_graph, M_4x4)

print("--- 4x4 Constrained Graph ---")
print(f"Marked Cells (M): {M_4x4}")

# Print degrees to verify connectivity changes
print("\nNode Degrees in Constrained Graph (checking for affected nodes):")
for r in range(4):
    for c in range(4):
        node = (r, c)
        degree = len(constrained_graph[node])
        # Note: The degrees of the marked cells (0,0), (0,1), (1,0), (1,1) should be reduced
        if node in M_4x4:
            print(f"Degree of {node}: {degree}")
        elif degree == 0:
            # This indicates an isolated node, which immediately prevents a perfect tiling
            print(f"WARNING: Isolated node found at {node} (degree 0). Tiling impossible.")

